function AttendancePage({ session }: { session: User }) {
  const query = useResource("attendance"); const canMark = hasPermission(session.role, "ATTENDANCE_MARK");
  if (query.isLoading) return <><PageHeader title="Attendance" /><Loading /></>;
  return <><PageHeader title="Attendance" description="Class registers for the current academic year." action={canMark && <Link href="/attendance/mark" className="inline-flex h-10 items-center gap-2 rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground"><Plus size={16} />Mark attendance</Link>} /><div className="table-card"><div className="table-scroll"><table><thead><tr><th>Date</th><th>Class</th><th>Section</th><th>Programme / shift</th><th>Present</th><th>Absent</th><th>Late</th><th>Marked by</th><th /></tr></thead><tbody>{(query.data || []).map((record) => <tr key={record.id}><td><Link className="table-link" href={`/attendance/${record.id}`}><strong>{date(record.date)}</strong></Link></td><td>{record.class}</td><td>{record.section}</td><td>{record.program}</td><td className="amount-positive">{record.entries.filter((entry) => entry.status === "Present").length}</td><td>{record.entries.filter((entry) => entry.status === "Absent").length}</td><td>{record.entries.filter((entry) => entry.status === "Late").length}</td><td>{record.markedBy}</td><td className="row-actions">{hasPermission(session.role, "ATTENDANCE_UPDATE") && <Link href={`/attendance/${record.id}`} className="icon-button" title="Update attendance"><Settings2 size={15} /></Link>}</td></tr>)}</tbody></table></div><div className="table-foot"><span>{query.data?.length || 0} attendance records</span><span className="table-foot-note">Use the class register to mark Present, Absent, or Late</span></div></div></>;
}
function AttendanceMark({ id, session }: { id?: string; session: User }) {
  const editing = !!id; const existing = useItem("attendance", id); const years = useResource("academicYears"); const programs = useResource("programs"); const classes = useResource("classes"); const sections = useResource("sections"); const students = useResource("students"); const save = useSaveAttendance(); const [, setLocation] = useLocation(); const canEdit = hasPermission(session.role, editing ? "ATTENDANCE_UPDATE" : "ATTENDANCE_MARK"); const [selection, setSelection] = useState({ academicYearId: "ay25", programId: "prg-day", classId: "cls-csc", sectionId: "sec-csc-a", date: "2025-05-14" }); const [entries, setEntries] = useState<{ studentId: string; studentName: string; status: AttendanceStatus }[]>([]);
  const classStudents = useMemo(() => { const schoolClass = classes.data?.find((item) => item.id === selection.classId); return (students.data || []).filter((student) => student.className === schoolClass?.name && student.section === sections.data?.find((section) => section.id === selection.sectionId)?.name); }, [classes.data, students.data, sections.data, selection.classId, selection.sectionId]);
  useEffect(() => { if (existing.item) { const record = existing.item as AttendanceRecord; setSelection({ academicYearId: record.academicYearId, programId: record.programId, classId: record.classId, sectionId: record.sectionId, date: record.date }); setEntries(record.entries); } }, [existing.item]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (!editing && classStudents.length && entries.length === 0) setEntries(classStudents.map((student) => ({ studentId: student.id, studentName: student.name, status: "Present" }))); }, [classStudents, editing, entries.length]);
  if (!canEdit) return <AccessState role={session.role} />; if (editing && existing.isLoading) return <Loading />;
  const year = years.data?.find((item) => item.id === selection.academicYearId); const program = programs.data?.find((item) => item.id === selection.programId); const schoolClass = classes.data?.find((item) => item.id === selection.classId); const section = sections.data?.find((item) => item.id === selection.sectionId);
  const updateSelection = (key: keyof typeof selection, value: string) => { if (key === "classId") { const firstSection = sections.data?.find((item) => item.classId === value); setSelection((current) => ({ ...current, classId: value, sectionId: firstSection?.id || "" })); if (!editing) setEntries([]); return; } setSelection((current) => ({ ...current, [key]: value })); };
  const submit = (event: FormEvent) => { event.preventDefault(); if (!entries.length) { toast({ title: "No students found", description: "Choose a class and section with enrolled students." }); return; } save.mutate({ id, academicYearId: selection.academicYearId, programId: selection.programId, classId: selection.classId, sectionId: selection.sectionId, date: selection.date, academicYear: year?.name || "", program: program?.name || "", class: schoolClass?.name || "", section: section?.name || "", markedBy: session.name, entries }, { onSuccess: () => { toast({ title: editing ? "Attendance updated" : "Attendance marked", description: "The class register has been saved." }); setLocation("/attendance"); }, onError: () => toast({ title: "Could not save attendance" }) }); };
  return <><button className="back-link page-back" onClick={() => setLocation("/attendance")}><ArrowLeft size={15} />Back to Attendance</button><PageHeader eyebrow={editing ? "Update register" : "Mark register"} title={editing ? "Update attendance" : "Mark attendance"} description="Choose the class context, then record each student’s status." /><form className="form-card attendance-form" onSubmit={submit}><div className="form-grid"><SelectField form={undefined as never} name="academicYearId" label="Academic year" options={(years.data || []).map((item) => [item.id, item.name])} /><SelectField form={undefined as never} name="programId" label="Programme / shift" options={(programs.data || []).map((item) => [item.id, item.name])} /><SelectField form={undefined as never} name="classId" label="Class" options={(classes.data || []).map((item) => [item.id, item.name])} /><SelectField form={undefined as never} name="sectionId" label="Section" options={(sections.data || []).filter((item) => item.classId === selection.classId).map((item) => [item.id, item.name])} /><div className="field"><label htmlFor="attendance-date">Date</label><input id="attendance-date" type="date" value={selection.date} onChange={(event) => updateSelection("date", event.target.value)} /></div></div><div className="attendance-select-grid">{(["academicYearId", "programId", "classId", "sectionId"] as const).map((key) => <label className="field" key={key}><span>{titleCase(key)}</span><select value={selection[key]} onChange={(event) => updateSelection(key, event.target.value)}>{(key === "academicYearId" ? years.data || [] : key === "programId" ? programs.data || [] : key === "classId" ? classes.data || [] : (sections.data || []).filter((item) => item.classId === selection.classId)).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>)}</div><div className="attendance-list"><div className="attendance-list-head"><span>Student</span><span>Status</span></div>{entries.map((entry) => <div className="attendance-row" key={entry.studentId}><div className="person-cell"><Avatar user={{ name: entry.studentName }} size="sm" /><strong>{entry.studentName}</strong></div><div className="attendance-controls">{(["Present", "Absent", "Late"] as AttendanceStatus[]).map((status) => <button type="button" key={status} className={`attendance-choice ${entry.status === status ? `attendance-choice-${status.toLowerCase()}` : ""}`} onClick={() => setEntries((current) => current.map((item) => item.studentId === entry.studentId ? { ...item, status } : item))}>{status}</button>)}</div></div>)}</div><div className="form-actions"><AppButton type="button" variant="ghost" onClick={() => setLocation("/attendance")}>Cancel</AppButton><AppButton type="submit" disabled={save.isPending}>{save.isPending ? "Saving…" : editing ? "Update register" : "Save attendance"}<Check size={16} /></AppButton></div></form></>;
}
function AttendanceDetail({ id, session }: { id: string; session: User }) { const query = useItem("attendance", id); const [, setLocation] = useLocation(); const canUpdate = hasPermission(session.role, "ATTENDANCE_UPDATE"); if (query.isLoading) return <Loading />; const item = query.item as AttendanceRecord | undefined; if (!item) return <Empty title="Attendance record not found" detail="This register may have been removed." />; return <><button className="back-link page-back" onClick={() => setLocation("/attendance")}><ArrowLeft size={15} />Back to Attendance</button><PageHeader eyebrow="Attendance register" title={`${item.class} · Section ${item.section}`} description={`${date(item.date)} · ${item.program} · Marked by ${item.markedBy}`} action={canUpdate && <Link href={`/attendance/${id}/edit`} className="inline-flex h-10 items-center gap-2 rounded-lg border border-border bg-card px-4 text-sm font-semibold"><Settings2 size={15} />Update register</Link>} /><div className="table-card"><div className="table-scroll"><table><thead><tr><th>Student</th><th>Status</th></tr></thead><tbody>{item.entries.map((entry) => <tr key={entry.studentId}><td>{entry.studentName}</td><td><Status>{entry.status}</Status></td></tr>)}</tbody></table></div><div className="table-foot"><span>{item.entries.length} students</span><span className="table-foot-note">Attendance detail</span></div></div></>; }

function TimetablePage() {
  const query = useResource("timetable"); if (query.isLoading) return <><PageHeader title="Timetable" /><Loading /></>;
  const days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]; return <><PageHeader title="Timetable" description="Published teaching schedule for the current academic year." /><div className="timetable-scroll"><div className="timetable-grid">{days.map((day) => <section className="timetable-day" key={day}><div className="timetable-day-head"><span>{day.slice(0, 3)}</span><strong>{day}</strong></div>{(query.data || []).filter((entry) => entry.day === day).map((entry) => <div className="timetable-entry" key={entry.id}><div className="eyebrow">{entry.time}</div><strong>{entry.subject}</strong><span>{entry.class} · {entry.section}</span><small>{entry.faculty} · {entry.room}</small></div>)}{!(query.data || []).some((entry) => entry.day === day) && <div className="timetable-empty">No periods</div>}</section>)}</div></div></>;
}

function Profile({ session, onRoleChange }: { session: User; onRoleChange: (role: Role) => void }) { return <><PageHeader eyebrow="Account" title="My profile" description="Your demo identity and access context." /><div className="profile-layout"><section className="panel profile-card"><Avatar user={session} size="lg" /><div className="eyebrow mt-5">Signed in as</div><h2>{session.name}</h2><p>{session.title}</p><div className="profile-details"><div><span>Email</span><strong>{session.email}</strong></div><div><span>Access level</span><strong>{session.role}</strong></div><div><span>Permissions</span><strong>{session.role === "College Admin" ? "All workspace permissions" : `${hasPermission(session.role, "STUDENT_READ") ? "Student records" : ""} ${hasPermission(session.role, "ATTENDANCE_READ") ? "· Attendance" : "· Administration"}`}</strong></div></div></section><section className="panel role-switcher"><div className="eyebrow">Demo controls</div><h2>Switch perspective</h2><p>Change role to explore how the same office looks to another teammate.</p>{roles.map((role) => <button key={role} className={`switch-role ${role === session.role ? "switch-role-active" : ""}`} onClick={() => { onRoleChange(role); toast({ title: "Perspective changed", description: `Now viewing Nalanda as ${role}.` }); }}>{role}{role === session.role ? <Check size={17} /> : <ArrowRight size={17} />}</button>)}</section></div></>; }

