function ParamBasicForm({ resource, session }: { resource: BasicResource; session: User }) { const { id } = useParams(); return <BasicForm resource={resource} id={id} session={session} />; }
function ParamBasicDetail({ resource, session }: { resource: BasicResource; session: User }) { const { id } = useParams(); return <BasicDetail resource={resource} id={id || ""} session={session} />; }
function ParamFeeForm({ session }: { session: User }) { const { id } = useParams(); return <FeeForm id={id} session={session} />; }
function ParamFeeDetail({ session }: { session: User }) { const { id } = useParams(); return <FeeDetail id={id || ""} session={session} />; }
function ParamComponentForm({ session }: { session: User }) { const { id } = useParams(); return <FeeComponentForm id={id} session={session} />; }
function ParamComponentDetail({ session }: { session: User }) { const { id } = useParams(); return <FeeComponentDetail id={id || ""} session={session} />; }
function ParamAttendanceMark({ session }: { session: User }) { const { id } = useParams(); return <AttendanceMark id={id} session={session} />; }
function ParamAttendanceDetail({ session }: { session: User }) { const { id } = useParams(); return <AttendanceDetail id={id || ""} session={session} />; }

function RoutedApp({ session, onLogout, onRoleChange }: { session: User; onLogout: () => void; onRoleChange: (role: Role) => void }) {
  return <Shell session={session} onLogout={onLogout}><Switch>
    <Route path="/dashboard"><Dashboard session={session} /></Route>
    <Route path="/academic-years/new"><Protected session={session} permission="CLASS_CREATE"><SetupForm resource="academicYears" session={session} /></Protected></Route><Route path="/academic-years/:id/edit"><Protected session={session} permission="CLASS_UPDATE"><ParamSetupForm resource="academicYears" session={session} /></Protected></Route><Route path="/academic-years/:id"><Protected session={session} permission="CLASS_READ"><ParamSetupDetail resource="academicYears" session={session} /></Protected></Route><Route path="/academic-years"><Protected session={session} permission="CLASS_READ"><SetupList resource="academicYears" session={session} /></Protected></Route>
    <Route path="/academic-programs/new"><Protected session={session} permission="SHIFT_CREATE"><SetupForm resource="programs" session={session} /></Protected></Route><Route path="/academic-programs/:id/edit"><Protected session={session} permission="SHIFT_UPDATE"><ParamSetupForm resource="programs" session={session} /></Protected></Route><Route path="/academic-programs/:id"><Protected session={session} permission="SHIFT_READ"><ParamSetupDetail resource="programs" session={session} /></Protected></Route><Route path="/academic-programs"><Protected session={session} permission="SHIFT_READ"><SetupList resource="programs" session={session} /></Protected></Route>
    <Route path="/classes/new"><Protected session={session} permission="CLASS_CREATE"><SetupForm resource="classes" session={session} /></Protected></Route><Route path="/classes/:id/edit"><Protected session={session} permission="CLASS_UPDATE"><ParamSetupForm resource="classes" session={session} /></Protected></Route><Route path="/classes/:id"><Protected session={session} permission="CLASS_READ"><ParamSetupDetail resource="classes" session={session} /></Protected></Route><Route path="/classes"><Protected session={session} permission="CLASS_READ"><SetupList resource="classes" session={session} /></Protected></Route>
    <Route path="/sections/new"><Protected session={session} permission="CLASS_CREATE"><SetupForm resource="sections" session={session} /></Protected></Route><Route path="/sections/:id/edit"><Protected session={session} permission="CLASS_UPDATE"><ParamSetupForm resource="sections" session={session} /></Protected></Route><Route path="/sections/:id"><Protected session={session} permission="CLASS_READ"><ParamSetupDetail resource="sections" session={session} /></Protected></Route><Route path="/sections"><Protected session={session} permission="CLASS_READ"><SetupList resource="sections" session={session} /></Protected></Route>
    <Route path="/students/new"><Protected session={session} permission="STUDENT_CREATE"><BasicForm resource="students" session={session} /></Protected></Route><Route path="/students/:id/edit"><Protected session={session} permission="STUDENT_UPDATE"><ParamBasicForm resource="students" session={session} /></Protected></Route><Route path="/students/:id"><Protected session={session} permission="STUDENT_READ"><ParamBasicDetail resource="students" session={session} /></Protected></Route><Route path="/students"><Protected session={session} permission="STUDENT_READ"><BasicList resource="students" session={session} /></Protected></Route>
    <Route path="/admissions/new"><Protected session={session} permission="ADMISSION_CREATE"><BasicForm resource="admissions" session={session} /></Protected></Route><Route path="/admissions/:id/edit"><Protected session={session} permission="ADMISSION_UPDATE"><ParamBasicForm resource="admissions" session={session} /></Protected></Route><Route path="/admissions/:id"><Protected session={session} permission="ADMISSION_READ"><ParamBasicDetail resource="admissions" session={session} /></Protected></Route><Route path="/admissions"><Protected session={session} permission="ADMISSION_READ"><BasicList resource="admissions" session={session} /></Protected></Route>
    <Route path="/staff/new"><Protected session={session} permission="STAFF_CREATE"><BasicForm resource="staff" session={session} /></Protected></Route><Route path="/staff/:id/edit"><Protected session={session} permission="STAFF_UPDATE"><ParamBasicForm resource="staff" session={session} /></Protected></Route><Route path="/staff/:id"><Protected session={session} permission="STAFF_READ"><ParamBasicDetail resource="staff" session={session} /></Protected></Route><Route path="/staff"><Protected session={session} permission="STAFF_READ"><BasicList resource="staff" session={session} /></Protected></Route>
    <Route path="/fees/new"><Protected session={session} permission="FEES_CREATE"><FeeForm session={session} /></Protected></Route><Route path="/fees/:id/edit"><Protected session={session} permission="FEES_UPDATE"><ParamFeeForm session={session} /></Protected></Route><Route path="/fees/:id"><Protected session={session} permission="FEES_READ"><ParamFeeDetail session={session} /></Protected></Route><Route path="/fees"><Protected session={session} permission="FEES_READ"><FeesPage session={session} /></Protected></Route>
    <Route path="/fee-components/new"><Protected session={session} permission="FEES_CREATE"><FeeComponentForm session={session} /></Protected></Route><Route path="/fee-components/:id/edit"><Protected session={session} permission="FEES_UPDATE"><ParamComponentForm session={session} /></Protected></Route><Route path="/fee-components/:id"><Protected session={session} permission="FEES_READ"><ParamComponentDetail session={session} /></Protected></Route><Route path="/fee-components"><Protected session={session} permission="FEES_READ"><FeeComponentsPage session={session} /></Protected></Route>
    <Route path="/attendance/mark"><Protected session={session} permission="ATTENDANCE_MARK"><AttendanceMark session={session} /></Protected></Route><Route path="/attendance/:id/edit"><Protected session={session} permission="ATTENDANCE_UPDATE"><ParamAttendanceMark session={session} /></Protected></Route><Route path="/attendance/:id"><Protected session={session} permission="ATTENDANCE_READ"><ParamAttendanceDetail session={session} /></Protected></Route><Route path="/attendance"><Protected session={session} permission="ATTENDANCE_READ"><AttendancePage session={session} /></Protected></Route>
    <Route path="/timetable"><Protected session={session} permission="TIMETABLE_READ"><TimetablePage /></Protected></Route><Route path="/profile"><Profile session={session} onRoleChange={onRoleChange} /></Route><Route path="/"><RedirectTo href="/dashboard" /></Route><Route component={NotFound} />
  </Switch></Shell>;
}

function Router() {
  const { session, logout, login } = useSession();
  if (!session) return <Switch><Route path="/forgot-password" component={ForgotPassword} /><Route path="/reset-password" component={ResetPassword} /><Route path="/login" component={Login} /><Route><RedirectTo href="/login" /></Route></Switch>;
  return <Switch><Route path="/login"><RedirectTo href="/dashboard" /></Route><Route><RoutedApp session={session} onLogout={() => { logout(); toast({ title: "Signed out", description: "Your demo session has ended." }); }} onRoleChange={(role) => login(role)} /></Route></Switch>;
}
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}><ErrorBoundary><Router /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;